values.content:
=Completa los campos faltantes.

Estado actual:
- Título: {{ $('Buscar Estado Pendiente').item.json.title }}
- Fecha: {{ $('Buscar Estado Pendiente').item.json.date || 'FALTA' }}
- Hora: {{ $('Buscar Estado Pendiente').item.json.time || 'FALTA' }}

Respuesta: "{{ $('Unificar Datos').item.json.userText }}"

Interpreta:
- "mañana" → {{ $now.plus({days:1}).toFormat('yyyy-MM-dd') }}
- "8pm" → "20:00"

JSON:
{
  "date": "YYYY-MM-DD" o null,
  "time": "HH:mm" o null,
  "durationMin": número o null
}

assignments.value:
={{ (() => {
  const intent = $json.intent;
  const missing = [];

  if (intent === 'ADD_REMINDER' || intent === 'ADD_EVENT') {
    if (!$json.date) missing.push('date');
    if (!$json.time) missing.push('time');
    if (intent === 'ADD_EVENT' && !$json.durationMin) missing.push('durationMin');
  }

  return {
    intent: $json.intent,
    title: $json.title,
    text: $json.text,
    date: $json.date,
    time: $json.time,
    durationMin: $json.durationMin,
    missing: missing,
    needsConfirm: missing.length > 0
  };
})() }}

